mut counter := 7
export func descend(n) {
  let stamp := n * 11 + 3
  if n == 0 { return counter + stamp + n }
  let nested := invoke(descend, n - 1)
  return nested + stamp + n
}
export func step(n) {
  counter += 1
  let stamp := n * 11 + 3
  if n == 0 { return counter + stamp + n }
  let nested := invoke(step, n - 1)
  return nested + stamp + n
}
export func read_counter() { return counter }

